#include "dynamic_objective.hpp"
#include "military_commander.hpp"
#include "resident/domains/travel/movement_exact_detail.hpp"
#include <algorithm>
#include <set>
#include <tuple>
namespace hanmo::resident {using namespace movement_detail;namespace {
bool active(const BattleUnit& u){return !u.withdrawn&&!u.fit.empty()&&u.morale>0;}
bool operational(const BattleUnit& u){return active(u)&&military_commander_loss(u)!=2;}
const DynamicObjectiveUnitRead& unit(const std::vector<DynamicObjectiveUnitRead>& units,const StableId& id){for(const auto& u:units)if(u.actual_unit.original_unit.unit_id==id)return u;fail("DynamicMilitaryObjectiveUnitRequired",id);}
bool refs_equal(const std::vector<SourceRef>& a,const std::vector<SourceRef>& z){if(a.size()!=z.size())return false;for(std::size_t n=0;n<a.size();++n)if(!same_source(a[n],z[n]))return false;return true;}
bool hold_equal(const DynamicMilitaryHoldState& a,const DynamicMilitaryHoldState& z,ExactArithmeticBudget b){if(a.index()!=z.index())return false;if(const auto* x=std::get_if<DynamicHolding>(&a)){const auto& y=std::get<DynamicHolding>(z);return same_moment(x->held_since,y.held_since,b)&&same_source(x->qualification_transition_ref,y.qualification_transition_ref);}if(const auto* x=std::get_if<DynamicHoldUnqualified>(&a))return same_source(x->last_condition_source_ref,std::get<DynamicHoldUnqualified>(z).last_condition_source_ref);return true;}
bool same_current(const DynamicMilitaryObjectiveCurrent& a,const DynamicMilitaryObjectiveCurrent& z,ExactArithmeticBudget b){if(a.objective_definition_ref!=z.objective_definition_ref||!same_moment(a.started_at,z.started_at,b)||!same_moment(a.deadline_at,z.deadline_at,b)||!hold_equal(a.hold_state,z.hold_state,b)||!same_source(a.last_transition_source_ref,z.last_transition_source_ref)||bool(a.outcome_source_ref)!=bool(z.outcome_source_ref)||(a.outcome_source_ref&&!same_source(*a.outcome_source_ref,*z.outcome_source_ref))||a.escaped_units.size()!=z.escaped_units.size())return false;for(std::size_t n=0;n<a.escaped_units.size();++n)if(a.escaped_units[n].unit_ref!=z.escaped_units[n].unit_ref||!same_source(a.escaped_units[n].actual_exit_source_ref,z.escaped_units[n].actual_exit_source_ref))return false;return true;}
}
Outcome<DynamicObjectiveEvaluation> evaluate_dynamic_military_objective(const DynamicObjectiveOriginalInputs& in,ExactArithmeticBudget b){return guard<DynamicObjectiveEvaluation>([&]{
 const auto& def=in.original_definition;const auto& timing=in.original_timing;const auto& current=in.current;const std::set<StableId> kinds{"repel","hold","breakthrough","escort","cover_retreat"};
 if(in.session_ref.empty()||in.generation<1||!kinds.count(def.kind)||def.id.empty()||def.side<0||def.side>1||def.required_units<0||def.id!=current.objective_definition_ref||def.id!=timing.objective_definition_ref||current.outcome_source_ref||compare(timing.deadline_duration.value,{},b)<=0||!same_moment(current.deadline_at,take(add_world_duration(current.started_at,timing.deadline_duration,b)),b)||take(compare_world_moments(current.started_at,in.effective_at,b))>0||take(compare_world_moments(in.effective_at,current.deadline_at,b))>0)fail("DynamicMilitaryObjectiveInputsRequired",in.session_ref);
 if((def.kind=="hold")!=bool(timing.hold_duration)||(def.kind=="hold")!=bool(def.point)||(def.kind=="hold")==std::holds_alternative<DynamicNotHold>(current.hold_state)||(timing.hold_duration&&compare(timing.hold_duration->value,{},b)<=0))fail("DynamicMilitaryObjectiveTimingMismatch",def.id);
 if(in.actual_cause_sources.empty()||in.actual_cause<DynamicObjectiveCause::actual_entry||in.actual_cause>DynamicObjectiveCause::objective_gate)fail("DynamicMilitaryObjectiveActualCauseRequired",in.session_ref);std::set<std::tuple<StableId,StableId,StableId>> causes;for(const auto& ref:in.actual_cause_sources)if(!source_valid(ref)||!causes.emplace(ref.domain,ref.kind,ref.id).second)fail("DynamicMilitaryObjectiveActualCauseRequired",ref.id);
 std::set<StableId> ids,escaped;Integer counts[2]={0,0},escaped_count=0;bool routing=false;for(const auto& u:in.actual_units){const auto& actual=u.actual_unit.original_unit;if(actual.unit_id.empty()||!ids.insert(actual.unit_id).second||actual.side<0||actual.side>1||actual.morale<0||actual.morale>100||!source_valid(u.actual_unit.position_source)||u.actual_unit.actual_qualification_sources.empty())fail("DynamicMilitaryObjectiveUnitRequired",actual.unit_id);for(const auto& source:u.actual_unit.actual_qualification_sources)if(!source_valid(source))fail("DynamicMilitaryObjectiveQualificationSourceRequired",actual.unit_id);if(operational(actual))++counts[actual.side];if(u.actual_routing_source){if(!source_valid(*u.actual_routing_source)||actual.withdrawn||actual.fit.empty()||actual.morale!=0)fail("DynamicMilitaryObjectiveRoutingSourceRequired",actual.unit_id);routing=true;}}
 if(ids.empty())fail("DynamicMilitaryObjectiveRosterRequired",in.session_ref);StableId prior;for(const auto& e:current.escaped_units){const auto& actual=unit(in.actual_units,e.unit_ref).actual_unit.original_unit;if(e.unit_ref<=prior||!source_valid(e.actual_exit_source_ref)||!actual.withdrawn||!escaped.insert(e.unit_ref).second)fail("DynamicMilitaryObjectiveExitSourceMismatch",e.unit_ref);prior=e.unit_ref;if(actual.side==def.side)++escaped_count;}
 for(const auto& u:in.actual_units)if(u.actual_unit.original_unit.withdrawn!=bool(escaped.count(u.actual_unit.original_unit.unit_id)))fail("DynamicMilitaryObjectiveExitCoverage",u.actual_unit.original_unit.unit_id);
 DynamicObjectiveEvaluation out;std::set<StableId> protected_ids;for(const auto& id:in.actual_protected_unit_refs)if(!protected_ids.insert(id).second||unit(in.actual_units,id).actual_unit.original_unit.side!=def.side)fail("DynamicMilitaryProtectedUnitMismatch",id);const bool protects=def.kind=="escort"||def.kind=="cover_retreat";if(protects!=!protected_ids.empty())fail("DynamicMilitaryProtectedUnitsRequired",def.id);
 // Continuous qualification is evaluated even if another original outcome
 // wins below; same-M false/true changes cannot be hidden by a terminal result.
 bool held=false;if(def.kind=="hold"){const MilitarySpatialPoint point{take(spatial_integer(def.point->q,b)),take(spatial_integer(def.point->r,b))};for(const auto& u:in.actual_units){const auto& actual=u.actual_unit.original_unit;if(!active(actual))continue;if(actual.side==def.side&&take(military_spatial_points_equal(u.actual_unit.actual_position,point,b)))out.actual_qualified_unit_refs.push_back(actual.unit_id);if(actual.side!=def.side&&compare(take(military_axial_length(u.actual_unit.actual_position,point,b)),integer(1,b),b)<=0)out.actual_contesting_unit_refs.push_back(actual.unit_id);}std::sort(out.actual_qualified_unit_refs.begin(),out.actual_qualified_unit_refs.end());std::sort(out.actual_contesting_unit_refs.begin(),out.actual_contesting_unit_refs.end());held=!out.actual_qualified_unit_refs.empty()&&out.actual_contesting_unit_refs.empty();const auto* previous=std::get_if<DynamicHolding>(&current.hold_state);if(previous&&(take(compare_world_moments(previous->held_since,in.effective_at,b))>0||!source_valid(previous->qualification_transition_ref)))fail("DynamicMilitaryHoldingSourceRequired",in.session_ref);if(bool(previous)!=held){DynamicObjectiveQualificationTransition transition;transition.objective_definition_ref=def.id;transition.from_state=previous?DynamicObjectiveQualification::holding:DynamicObjectiveQualification::unqualified;transition.to_state=held?DynamicObjectiveQualification::holding:DynamicObjectiveQualification::unqualified;if(previous)transition.previous_holding_source_ref=previous->qualification_transition_ref;transition.cause_kind=in.actual_cause;transition.cause_source_refs=in.actual_cause_sources;transition.actual_qualified_unit_refs=out.actual_qualified_unit_refs;transition.actual_contesting_unit_refs=out.actual_contesting_unit_refs;out.qualification_transition=std::move(transition);}}
 auto result=[&](Integer side,const char* reason){out.outcome=MilitaryBattleResult{side,reason,{}};};const auto side=def.side,enemy=1-side;
 if(protects){bool delivered=true;for(const auto& id:in.actual_protected_unit_refs){const auto& u=unit(in.actual_units,id).actual_unit.original_unit;if(!u.withdrawn&&u.fit.empty()){result(enemy,"ProtectedMilitaryUnitLost");return out;}if(!u.withdrawn)delivered=false;}if(delivered&&(def.kind=="escort"||escaped_count>=def.required_units)){result(side,def.kind=="escort"?"EscortDelivered":"RetreatCovered");return out;}}
 if(def.kind=="breakthrough"&&escaped_count>=def.required_units){result(side,"MilitaryBreakthrough");return out;}
 if(held)if(const auto* holding=std::get_if<DynamicHolding>(&current.hold_state)){const auto due=take(add_world_duration(holding->held_since,*timing.hold_duration,b));const auto order=take(compare_world_moments(in.effective_at,due,b));if(order>0)fail("DynamicMilitaryHoldGateSkipped",in.session_ref);if(order==0){result(side,"MilitaryPointHeld");return out;}}
 const bool before_deadline=take(compare_world_moments(in.effective_at,current.deadline_at,b))<0;
 // Original routing responsibility delays only the operational-zero result;
 // the real deadline and protected-unit/exit results retain their precedence.
 if(!(routing&&before_deadline)){if(counts[side]==0){result(counts[enemy]==0?-1:enemy,counts[enemy]==0?"MutualMilitaryRout":"MilitarySideRepelled");return out;}if(def.kind=="repel"&&counts[enemy]==0){result(side,"EnemyMilitaryRepelled");return out;}}
 if(!before_deadline)result(def.kind=="repel"?-1:enemy,"MilitaryObjectiveTimeout");return out;
});}
Outcome<DynamicObjectiveQualificationApplication> apply_dynamic_military_objective_qualification_in_candidate(CommonStore& common,const MilitaryState& military,MilitaryExactState& state,const DynamicMilitarySessionOriginalRead& sessions,const DynamicMilitaryObjectiveOriginalRead& originals,const CurrentMomentRead& clock,const StableId& session,Integer generation,DynamicObjectiveCause cause,const std::vector<SourceRef>& causes,ExactArithmeticBudget b){return guard<DynamicObjectiveQualificationApplication>([&]{auto* current=state.session_current_states.find(dynamic_military_session_key(session,generation));if(!current||!std::holds_alternative<DynamicMilitaryActive>(current->lifecycle))fail("DynamicMilitaryActiveObjectiveRequired",session);const auto at=take(clock.read_current_moment());const auto in=take(originals.read_actual_objective_inputs(*current,at,cause,causes));if(in.session_ref!=session||in.generation!=generation||!same_moment(in.effective_at,at,b)||in.actual_cause!=cause||!refs_equal(in.actual_cause_sources,causes)||!same_current(in.current,current->objective_current,b)||in.original_timing.definition_lock_ref!=current->definition_lock_ref)fail("DynamicMilitaryObjectiveActualInputMismatch",session);DynamicObjectiveQualificationApplication out;out.evaluation=take(evaluate_dynamic_military_objective(in,b));if(out.evaluation.qualification_transition)out.actual_transition=MomentOwnerSource{take(apply_dynamic_military_session_transition_in_candidate(common,military,state,sessions,clock,session,generation,*out.evaluation.qualification_transition,b)),2};return out;});}
Outcome<std::optional<DynamicObjectiveGateRead>> predict_dynamic_military_objective_gate(const CommonStore& common,const MilitaryState& military,const MilitaryExactState& state,const DynamicMilitarySessionOriginalRead& originals,const StableId& session,Integer generation,const WorldMoment& now,ExactArithmeticBudget b){return guard<std::optional<DynamicObjectiveGateRead>>([&]()->std::optional<DynamicObjectiveGateRead>{const auto* current=take(read_dynamic_military_session_current(common,military,state,originals,session,generation,now,b));if(!std::holds_alternative<DynamicMilitaryActive>(current->lifecycle))return std::nullopt;const auto definition=take(originals.read_session_definition(current->definition_lock_ref));DynamicObjectiveGateRead out{session,generation,current->objective_current.deadline_at,current->initialization_source_ref};if(const auto* held=std::get_if<DynamicHolding>(&current->objective_current.hold_state)){if(!definition.hold_duration)fail("DynamicMilitaryHoldDurationRequired",session);const auto at=take(add_world_duration(held->held_since,*definition.hold_duration,b));if(take(compare_world_moments(at,out.at,b))<0)out={session,generation,at,held->qualification_transition_ref};}if(take(compare_world_moments(out.at,now,b))<0)fail("DynamicMilitaryObjectiveGateSkipped",session);return out;});}
}
